import {readSketch,readConditions,readObjects} from './read-design-ui.js';
import {architectureOptions,architectureSources,architectureDriverContext,assessInteraction,interactionReasoningGraph,interactionContext,interactionReceiptCurrent,interactionSourceReceipt,knowledgeConcern} from './architecture-knowledge.js';
import {releasedDesignConcerns,releasedDesignConcern} from './domain-knowledge.js';
